using System.ComponentModel.DataAnnotations; using dxpmt.Data; using dxpmt.Domain; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace dxpmt.Pages.Requirements;
public sealed class CreateModel(ApplicationDbContext database):PageModel { [BindProperty] public InputModel Input{get;set;}=new(); public ImprovementCase Case{get;private set;}=null!; public List<WorkItem> WorkItems{get;private set;}=[]; public async Task<IActionResult> OnGetAsync(int caseId){return await Load(caseId)?Page():NotFound();} public async Task<IActionResult> OnPostAsync(int caseId){if(!await Load(caseId))return NotFound();if(Input.WorkItemId.HasValue&&!WorkItems.Any(x=>x.Id==Input.WorkItemId))ModelState.AddModelError("Input.WorkItemId","この案件のTo-Be作業を選択してください。");if(!RequirementCategories.All.Contains(Input.Category)||!RequirementStatuses.All.Contains(Input.Status)||!CasePriorities.All.Contains(Input.Priority))ModelState.AddModelError("", "選択値を確認してください。");if(!ModelState.IsValid)return Page();var now=DateTime.UtcNow;var seq=(await database.Requirements.Where(x=>x.CaseId==caseId).MaxAsync(x=>(int?)x.Sequence)??0)+1;var item=new Requirement{CaseId=caseId,WorkItemId=Input.WorkItemId,Sequence=seq,Category=Input.Category,Title=Input.Title.Trim(),Description=Input.Description.Trim(),Priority=Input.Priority,AcceptanceCriteria=Input.AcceptanceCriteria?.Trim()??"",ImplementationApproach=Input.ImplementationApproach?.Trim()??"",Status=Input.Status,CreatedAt=now,UpdatedAt=now};database.Requirements.Add(item);await database.SaveChangesAsync();if(item.WorkItemId.HasValue){database.TraceLinks.Add(new TraceLink{CaseId=caseId,SourceType=TraceLinkTypes.WorkItem,SourceId=item.WorkItemId.Value,TargetType=TraceLinkTypes.Requirement,TargetId=item.Id,CreatedAt=now});await database.SaveChangesAsync();}return RedirectToPage("Index",new{caseId});} async Task<bool> Load(int id){var c=await database.Cases.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);if(c is null)return false;Case=c;WorkItems=await database.WorkItems.AsNoTracking().Where(x=>x.CaseId==id&&x.WorkType==WorkItemTypes.ToBe&&!x.IsDeleted).OrderBy(x=>x.Sequence).ToListAsync();return true;} public sealed class InputModel{[Display(Name="To-Be作業")]public int? WorkItemId{get;set;}[Required,Display(Name="分類")]public string Category{get;set;}="業務";[Required,Display(Name="要求事項")]public string Title{get;set;}="";[Required,Display(Name="内容")]public string Description{get;set;}="";[Required,Display(Name="優先度")]public string Priority{get;set;}=CasePriorities.Medium;[Display(Name="受入条件")]public string? AcceptanceCriteria{get;set;}[Display(Name="対応方式")]public string? ImplementationApproach{get;set;}[Required,Display(Name="状態")]public string Status{get;set;}="検討中";} }
